import { useCallback, useRef } from 'react';
import {
  ReactFlow,
  ReactFlowProvider,
  addEdge,
  useNodesState,
  useEdgesState,
  Controls,
  Background,
  MiniMap
} from '@xyflow/react';
import '@xyflow/react/dist/style.css';
import FiberDeviceNode from './FiberDeviceNode';

const nodeTypes = { fiberDevice: FiberDeviceNode };

// 👇 Inner component that uses React Flow hooks
function FlowContent({ onElementSelect, nodes, setNodes, edges, setEdges }) {
  
  // ✅ Properly handle node/edge changes (position, selection, etc.)
  const onNodesChange = useCallback((changes) => {
    setNodes((nds) => {
      // Apply changes: position updates, selection, removal, etc.
      return nds.map((node) => {
        const change = changes.find((c) => c.id === node.id);
        if (change?.position) {
          return { ...node, position: change.position };
        }
        if (change?.selected !== undefined) {
          return { ...node, selected: change.selected };
        }
        return node;
      });
    });
  }, [setNodes]);

  const onEdgesChange = useCallback((changes) => {
    setEdges((eds) => {
      return eds.map((edge) => {
        const change = changes.find((c) => c.id === edge.id);
        if (change?.selected !== undefined) {
          return { ...edge, selected: change.selected };
        }
        return edge;
      });
    });
  }, [setEdges]);

  const onConnect = useCallback(
    (params) => {
      const newEdge = {
        ...params,
        id: `edge-${params.source}-${params.target}-${Date.now()}`,
        label: 'Fiber Link',
        animated: true,
        style: { stroke: '#64748b', strokeWidth: 2 },
        labelStyle: { fill: '#334155', fontWeight: 500, fontSize: '11px' },
        labelShowBg: true,
        labelBgStyle: { fill: '#fff', stroke: '#cbd5e1' },
        labelBgPadding: [4, 4]
      };
      setEdges((eds) => addEdge(newEdge, eds));
    },
    [setEdges]
  );

  const onDragOver = useCallback((event) => {
    event.preventDefault();
    event.dataTransfer.dropEffect = 'move';
  }, []);

  const onDrop = useCallback(
    (event) => {
      event.preventDefault();
      const type = event.dataTransfer.getData('application/reactflow');
      if (!type) return;

      // Get canvas position using ref
      const reactFlowWrapper = event.currentTarget.querySelector('.react-flow');
      if (!reactFlowWrapper) return;
      
      const bounds = reactFlowWrapper.getBoundingClientRect();
      const position = {
        x: event.clientX - bounds.left,
        y: event.clientY - bounds.top,
      };

      const newNode = {
        id: `${type}-${Date.now()}-${Math.random().toString(36).substr(2, 5)}`,
        type: 'fiberDevice',
        position,
        // ✅ Explicitly enable dragging
        draggable: true,
        data: { type, hostname: '', ip: '' },
      };
      setNodes((nds) => [...nds, newNode]);
    },
    [setNodes]
  );

  const onNodeClick = useCallback((_, node) => {
    onElementSelect({ type: 'node', id: node.id });
  }, [onElementSelect]);

  const onEdgeClick = useCallback((_, edge) => {
    onElementSelect({ type: 'edge', id: edge.id });
  }, [onElementSelect]);

  const onPaneClick = useCallback(() => {
    onElementSelect(null);
  }, [onElementSelect]);

  return (
    <ReactFlow
      nodes={nodes}
      edges={edges}
      onNodesChange={onNodesChange}  // ✅ Critical for drag position updates
      onEdgesChange={onEdgesChange}
      onConnect={onConnect}
      onDragOver={onDragOver}
      onDrop={onDrop}
      onNodeClick={onNodeClick}
      onEdgeClick={onEdgeClick}
      onPaneClick={onPaneClick}
      nodeTypes={nodeTypes}
      fitView
      fitViewOptions={{ padding: 0.2 }}
      className="react-flow-container"
      minZoom={0.2}
      maxZoom={2}
      // ✅ Enable pan on spacebar + drag for better UX
      panOnDrag={[1, 2]}  // Left + right mouse button
      panOnScroll={true}
      selectionOnDrag={true}
    >
      <Background color="#e2e8f0" gap={24} size={1} />
      <Controls showInteractive={false} />
      <MiniMap 
        nodeColor={(node) => {
          const colors = { router: '#ef4444', switch: '#f59e0b', olt: '#10b981', ont: '#3b82f6' };
          return colors[node.data?.type] || '#64748b';
        }}
        maskColor="rgba(241, 245, 249, 0.85)"
      />
    </ReactFlow>
  );
}

// 👇 Export with Provider wrapper
export default function NetworkFlow(props) {
  return (
    <ReactFlowProvider>
      <FlowContent {...props} />
    </ReactFlowProvider>
  );
}
